INSERT INTO decision_nodes VALUES
  ('200-start','glories-200-tra','start','Inicio','Ejecuta las acciones iniciales y determina la peligrosidad del vertido.',211),
  ('200-danger','glories-200-tra','question','Peligrosidad','¿El vertido ha sido determinado como peligroso?',211),
  ('200-lanes','glories-200-tra','question','Afectación','¿Afecta a dos o más carriles?',211),
  ('200-cleared','glories-200-tra','question','Seguimiento','¿El vertido ha sido limpiado y ha finalizado la situación de riesgo?',211),
  ('200-end','glories-200-tra','terminal','Fin de la situación de riesgo','Restablecer las condiciones normales y desactivar el PAU en fase de alerta.',211),
  ('240-start','glories-240-tra','start','Inicio','Verifica la incidencia, activa el PAU y cierra el tubo.',227),
  ('240-type','glories-240-tra','question','Tipología','¿Qué se observa?',227),
  ('240-cleared','glories-240-tra','question','Seguimiento','¿Ha finalizado la incidencia y se ha retirado el animal o peatón?',227),
  ('240-end','glories-240-tra','terminal','Fin de la situación de riesgo','Restablecer condiciones normales y desactivar el PAU en alerta.',227),
  ('250-start','glories-250-tra','start','Inicio','Verifica el vehículo y ejecuta el corte de carril.',230),
  ('250-cleared','glories-250-tra','question','Seguimiento','¿El vehículo ha sido retirado y ha finalizado el riesgo?',230),
  ('250-end','glories-250-tra','terminal','Fin de la situación de riesgo','Restablecer condiciones normales y desactivar el PAU en alerta.',230),
  ('400-start','glories-400-foc','start','Inicio de emergencia','Activa inmediatamente el PAU en emergencia y aplica las medidas iniciales.',311),
  ('400-location','glories-400-foc','question','Ubicación','¿Dónde se localiza el incendio o explosión?',311),
  ('400-spread','glories-400-foc','question','Evolución','¿Existe evolución del incidente o riesgo hacia el interior del túnel?',311),
  ('400-cleared','glories-400-foc','question','Seguimiento','¿El Cap d’Emergència confirma el fin del incidente?',311),
  ('400-end','glories-400-foc','terminal','Fin de la situación de riesgo','Restablecer condiciones normales y desactivar el PAU en emergencia cuando corresponda.',311);
